@@ -0,0 +1,54 @@
+package patcher_test
+
+import (
+	"context"
+	"testing"
+	"time"
+
+	"github.com/expr-lang/expr"
+)
+
+type envTwoCalls struct {
+	Ctx context.Context `expr:"ctx"`
+}
+
+func (envTwoCalls) Now3(ctx context.Context) time.Time { return time.Now() }
+func (envTwoCalls) Date3(ctx context.Context) time.Time {
+	return time.Date(2000, 1, 1, 0, 0, 0, 0, time.UTC)
+}
+func (envTwoCalls) Add3(ctx context.Context, a, b int) int { return a + b }
+
+func TestWithContext_two_calls_within_one_call(t *testing.T) {
+	fns := []expr.Option{
+		expr.Function("now2", func(params ...any) (any, error) { return time.Now(), nil }, new(func(context.Context) time.Time)),
+		expr.Function("date2", func(params ...any) (any, error) { return time.Date(2000, 1, 1, 0, 0, 0, 0, time.UTC), nil }, new(func(context.Context) time.Time)),
+		expr.Function("add2", func(params ...any) (any, error) { return params[1].(int) + params[2].(int), nil }, new(func(context.Context, int, int) int)),
+	}
+	for _, code := range []string{
+		"now2().After(date2())", "date2().Before(now2())", "Now3().After(Date3())",
+		"Now3().After(date2())", "add2(add2(1, 2), add2(3, 4))", "Add3(Add3(1, 2), add2(3, 4))",
+		"now2().After(date2()) && Now3().After(Date3())",
+		"[now2(), date2()][0].After(date2())",
+		"let x = date2(); now2().After(x)",
+	} {
+		opts := append([]expr.Option{expr.Env(envTwoCalls{}), expr.WithContext("ctx")}, fns...)
+		p, err := expr.Compile(code, opts...)
+		if err != nil {
+			t.Errorf("%s: %v", code, err)
+			continue
+		}
+		_, err = expr.Run(p, envTwoCalls{Ctx: context.Background()})
+		if err != nil {
+			t.Errorf("%s: %v", code, err)
+		}
+	}
+}
+
+func TestWithContext_errors_are_kept(t *testing.T) {
+	for _, code := range []string{"Add3(1)", "Now3(1, 2)"} {
+		_, err := expr.Compile(code, expr.Env(envTwoCalls{}), expr.WithContext("ctx"))
+		if err == nil {
+			t.Errorf("%s: expected error", code)
+		}
+	}
+}

